/**
 * THE GATE:
 * Inspects inbound message for staff authorization (prefix /staff, #staff, [staff], or PIN).
 * Sets role: BACK_OFFICE or GUEST.
 */
const raw = ($input.item.json.chatInput || $input.item.json.query || $input.item.json.input || '').trim();
const low = raw.toLowerCase();

const isStaff = 
  low.startsWith('/staff') || 
  low.startsWith('#staff') || 
  low.startsWith('[staff]') ||
  low.includes('pin: 8888') ||
  low.includes('staff:') ||
  low.includes('duty manager');

const cleanMessage = raw
  .replace(/^\/(staff|bo)\s*/i, '')
  .replace(/^#(staff|bo)\s*/i, '')
  .replace(/^\[(staff|bo)\]\s*/i, '')
  .replace(/pin:\s*8888/i, '')
  .trim();

return {
  json: {
    chatInput: cleanMessage || raw,
    originalInput: raw,
    role: isStaff ? 'BACK_OFFICE' : 'GUEST'
  }
};

